UPDATE TRAVEL_PLAN
   SET START_DATE = #{startDate},
       END_DATE = #{endDate},
       VERSION_NO = VERSION_NO + 1,
       UPDATED_AT = CURRENT_TIMESTAMP
 WHERE PLAN_ID = #{planId}
   AND OWNER_MEMBER_ID = #{memberId}
   AND PLAN_STATUS = 'ACTIVE'
   AND VERSION_NO = #{versionNo}

UPDATE TRAVEL_PLAN
   SET TITLE = #{title},
       VISIBILITY = #{visibility},
       VERSION_NO = VERSION_NO + 1,
       UPDATED_AT = CURRENT_TIMESTAMP
 WHERE PLAN_ID = #{planId}
   AND OWNER_MEMBER_ID = #{memberId}
   AND PLAN_STATUS = 'ACTIVE'
   AND VERSION_NO = #{versionNo}
